function sendCompletion(response: ServerResponse, model: string, body: Record<string, any>, workspace: string): void {
  const messages = Array.isArray(body.messages) ? body.messages : []
  const tools = Array.isArray(body.tools) ? body.tools : []
  const afterTool = messages.some((message: any) => message?.role === 'tool')
  const writeTool = tools.find((tool: any) => tool?.function?.name?.endsWith('__write'))?.function?.name
  const delta =
    !afterTool && writeTool
      ? {
          role: 'assistant',
          tool_calls: [
            {
              index: 0,
              id: 'gate-v-write',
              type: 'function',
              function: {
                name: writeTool,
                arguments: JSON.stringify({
                  path: join(workspace, 'gate-v-approved.txt'),
                  content: 'Gate V approved filesystem operation.\n'
                })
              }
            }
          ]
        }
      : { role: 'assistant', content: 'Gate V completed after the approved filesystem operation.' }
  const finishReason = !afterTool && writeTool ? 'tool_calls' : 'stop'

