// Schema definition
export const WriteToolSchema = z.object({
  file_path: z.string().describe('The path to the file to write'),
  content: z.string().describe('The content to write to the file')
})

// Tool definition with detailed description
export const writeToolDefinition = {
  name: 'write',
  description: `Writes a file to the local filesystem.

- This tool will overwrite the existing file if one exists at the path
- You MUST use the read tool first to understand what you're overwriting
- ALWAYS prefer using the 'edit' tool for existing files
- NEVER proactively create documentation files unless explicitly requested
- Parent directories will be created automatically if they don't exist
- The file_path must resolve within the configured workspace root`,
  inputSchema: z.toJSONSchema(WriteToolSchema)
}

// Handler implementation
export async function handleWriteTool(args: unknown, baseDir: string) {
  const parsed = WriteToolSchema.safeParse(args)
  if (!parsed.success) {
    throw new Error(`Invalid arguments for write: ${parsed.error}`)
  }

private disposition(toolName: string): 'approve' | 'deny' | 'prompt' {
  const agent = agentService.getAgent(this.options.agentId)
  if (!agent) return 'deny'
  if ((agent.disabledTools ?? []).map(toUarToolName).includes(toolName)) return 'deny'
  const mode = agent.configuration?.permission_mode ?? 'default'
  if (mode === 'plan') return 'deny'

  const linkedChannel = resolveLinkedNotifyChannel(this.options.sessionId, agent.id)
  const mountedServers = resolveMountedMcpServers(agent, {
    browserEnabled: application.get('PreferenceService').get('app.browser.agent_control.enabled'),
    channelLinked: linkedChannel !== null
  })
  const builtin = findBuiltinToolPolicy(`mcp__${toolName}`, mountedServers)
  if (builtin?.approval === 'auto') return 'approve'
  if (builtin?.approval === 'required') {
    return mode === 'bypassPermissions' && builtin.bypassApproval === 'lift' ? 'approve' : 'prompt'
  }
  if (mode === 'bypassPermissions' || mode === 'auto') return 'approve'
  if (mode === 'acceptEdits' && this.isManagedFilesystemTool(toolName)) return 'approve'
  return 'prompt'

class ToolApprovalLedger {
  private readonly approved = new Map<string, string[]>()

  approve(identity: UarToolCallIdentity): void {
    const key = toolCallFingerprint(identity.toolName, identity.input)
    const calls = this.approved.get(key) ?? []
    calls.push(identity.toolCallId)
    this.approved.set(key, calls)
  }

  revoke(identity: UarToolCallIdentity): void {
    const key = toolCallFingerprint(identity.toolName, identity.input)
    const calls = this.approved.get(key)
    if (!calls) return
    const index = calls.indexOf(identity.toolCallId)
    if (index >= 0) calls.splice(index, 1)
    if (calls.length === 0) this.approved.delete(key)
  }

  consume(toolName: string, input: Record<string, unknown>): boolean {
    const key = toolCallFingerprint(toolName, input)
    const calls = this.approved.get(key)
    if (!calls?.length) return false
    calls.shift()
    if (calls.length === 0) this.approved.delete(key)
    return true
  }
}

type JsonRpcCall = { id: unknown }

function findDeniedToolCall(body: unknown, serverName: string, approvals: ToolApprovalLedger): JsonRpcCall | undefined {
  const messages = Array.isArray(body) ? body : [body]
  for (const message of messages) {
    if (!isRecord(message) || message.method !== 'tools/call' || !isRecord(message.params)) continue
    const name = message.params.name
    const args = message.params.arguments
    if (typeof name !== 'string') return { id: message.id ?? null }
    const input = isRecord(args) ? args : {}
    const toolName = sanitizeToolName(`${serverName}__${name}`)
    if (!approvals.consume(toolName, input)) return { id: message.id ?? null }
  }
  return undefined

for (idx, tool_call) in tool_calls.iter().enumerate() {
    let tool_name = &tool_call.function.name;
    let sequence = (u64::from(step) << 32) | idx as u64;
    let Some(descriptor) = descriptors.get(tool_name) else {
        yield NormalizedEvent::Error {
            message: format!(
                "No descriptor exists for requested tool '{tool_name}'"
            ),
            code: Some("UNKNOWN_TOOL_STATE_UNRECOVERED".to_string()),
        };
        return;
    };
    let preadmitted = admitted_calls.pop_front();
    let admitted_by_host = preadmitted.is_some();
    let arguments = match preadmitted.unwrap_or_else(|| {
        validate::validate(&descriptor.validator, &tool_call.function.arguments)
            .map_err(|error| error.model_result().to_string())
    }) {
        Ok(arguments) => arguments,
        Err(error) => {
            let source = Self::canonical_source_for(tool_name, descriptor);
            let content = match orchestrator
                .preserve_terminal_tool_failure(
                    sequence,
                    &tool_call.id,
                    tool_name,
                    source,
                    error,
                )
                .await
            {
                Ok(content) => content,
                Err(error) => {
                    yield NormalizedEvent::Error {
                        message: error.to_string(),
                        code: Some(
                            "TERMINAL_RESULT_PERSISTENCE_FAILED".to_string(),
                        ),
                    };
                    return;
                }
            };
            yield NormalizedEvent::ToolResult {
                id: tool_call.id.clone(),
                name: tool_name.clone(),
                content: content.clone(),
                success: false,
            };
            message_json.push(serde_json::json!({
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": content
            }));
            canonical_message_json.push(
                message_json
                    .last()
                    .cloned()
                    .expect("invalid tool result was just appended"),
            );
            continue;
        }
    };
    let output_policy = descriptor
        .output_limit
        .unwrap_or(orchestrator.tool_output_policy);

    tracing::info!(
        request_id = %request_id,
        iteration = iteration,
        tool_index = idx,
        tool_id = %tool_call.id,
        tool_name = %tool_name,
        "Executing tool call"
    );

    // Check tool approval gate if configured
    if !admitted_by_host && let Some(ref gate) = orchestrator.tool_approval_gate {
        let result = gate(
            tool_call.id.clone(),
            tool_name.clone(),
            descriptor.approval_class,
            tool_call.function.arguments.clone(),
            idx,
        ).await;

/// Parse raw model arguments and validate the resulting JSON value.
///
/// # Errors
///
/// Returns [`InvalidArguments`] for either malformed JSON or a schema
/// violation. The caller returns this error to the model and must not execute
/// the tool.
pub fn validate(validator: &Validator, arguments_json: &str) -> Result<Value, InvalidArguments> {
    let arguments =
        serde_json::from_str::<Value>(arguments_json).map_err(|error| InvalidArguments {
            message: format!("failed to parse tool arguments: {error}"),
        })?;
    let errors = validator
        .iter_errors(&arguments)
        .map(|error| error.to_string())
        .collect::<Vec<_>>();
    if errors.is_empty() {
        Ok(arguments)
    } else {
        Err(InvalidArguments {
            message: errors.join("; "),
        })
    }

fn mcp_descriptor(
    compiler: &ValidatorCompiler,
    server: &str,
    provider_name: &str,
    tool: &Tool,
) -> Result<Arc<ToolDescriptor>, ToolAssemblyError> {
    let input_schema = Value::Object((*tool.input_schema).clone());
    let validator = compiler.compile(provider_name, &input_schema)?;
    let effect = if tool
        .annotations
        .as_ref()
        .is_some_and(|annotations| annotations.read_only_hint == Some(true))
    {
        ToolEffect::ReadOnly
    } else {
        ToolEffect::Unknown
    };
    Ok(Arc::new(ToolDescriptor {
        id: format!("{server}::{}", tool.name),
        provider_name: provider_name.to_string(),
        description: tool.description.as_deref().unwrap_or_default().to_string(),
        source: ToolSource::Mcp,
        server: Some(server.to_string()),
        input_schema,
        validator,
        effect,
        // MCP annotations are untrusted. readOnlyHint affects scheduling only.
        approval_class: ApprovalClass::Required,
        sandbox_required: false,
        concurrency_key: None,
        exposure: Exposure::Eager,
        output_limit: None,
    }))
}

